export default function CursorOverlay({ cursors, width, height }) {
  // cursors: { [userId]: { x, y, name, color } }
  return (
    <svg
      className="absolute inset-0 pointer-events-none"
      width={width} height={height}
      style={{ zIndex: 10 }}
    >
      {Object.entries(cursors).map(([id, { x, y, name, color }]) => (
        <g key={id} transform={`translate(${x},${y})`}>
          {/* Arrow cursor shape */}
          <path d="M0 0 L0 14 L4 10 L7 16 L9 15 L6 9 L11 9 Z"
            fill={color} stroke="white" strokeWidth="0.8"/>
          {/* Name label */}
          <rect x="12" y="12" width={name.length * 7 + 10} height="18" rx="4" fill={color}/>
          <text x="17" y="25" style={{ fontSize: 11, fill: '#fff', fontFamily: 'inherit' }}>
            {name}
          </text>
        </g>
      ))}
    </svg>
  );
}
